    hay = name if case_sensitive else name.casefold()
    def atom(term):
        term=term.strip()
        if term.startswith('regex:'):
            try:return re.search(term[6:],name,0 if case_sensitive else re.I) is not None
            except re.error:return False
        needle=term if case_sensitive else term.casefold()
        return needle in hay
    if pattern.upper().startswith('NOT '):
        return not atom(pattern[4:])
    if ' XOR ' in pattern:
        return sum(atom(x) for x in re.split(r'\s+XOR\s+',pattern,flags=re.I)) == 1
    if ' AND ' in pattern:
        return all(atom(x) for x in re.split(r'\s+AND\s+',pattern,flags=re.I))
    if ' OR ' in pattern:
        return any(atom(x) for x in re.split(r'\s+OR\s+',pattern,flags=re.I))
    if pattern.startswith('+'):
